const waveformStyle=document.createElement("link");waveformStyle.rel="stylesheet";waveformStyle.href="./waveforms.css?v=1";document.head.appendChild(waveformStyle);const schematicStyle=document.createElement("link");schematicStyle.rel="stylesheet";schematicStyle.href="./schematic-engine.css?v=1";document.head.appendChild(schematicStyle);const topologies=window.POWER_TOPOLOGIES,flows=window.INDUSTRY_FLOWS;let activeId=topologies[0]?.id,zoom={system:1,schematic:1};
const oldCircuits=window.TVS_CIRCUITS||[
"USB 2.0","USB 3.x","USB-C VBUS","HDMI","Ethernet","PoE","CAN","CAN-FD","RS-485","RS-232","12V DC 输入","24V DC 输入","48V DC 输入","54V 热插拔","PLC DI","PLC DO","继电器","接触器","电磁阀","MOSFET D-S","MOSFET G-S","BMS CAN","BMS 接触器","CCTV PoE","数据中心 Hot-Swap"
].map((title,i)=>({title,group:i<4?"高速接口":i<10?"通信接口":i<14?"电源":i<16?"工业 I/O":i<19?"感性负载":i<21?"MOSFET":i<23?"储能":"安防/数据中心"}));
document.querySelectorAll(".tabs button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".tabs button").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));document.querySelector(`#${b.dataset.page}`).classList.add("active")});
const esc=s=>String(s).replace(/[&<>]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[m]));
function moduleBox(x,y,w,title,sub,protectedNode=false){return `<g class="module ${protectedNode?'protected':''}"><rect x="${x}" y="${y}" width="${w}" height="76" rx="3"/><text class="title" x="${x+w/2}" y="${y+31}">${esc(title)}</text><text class="sub" x="${x+w/2}" y="${y+53}">${esc(sub||'')}</text></g>`}
function systemSvg(t){const n=t.stages.length,gap=24,w=Math.max(118,Math.min(155,(1050-gap*(n+1))/n));let x=gap,out=`<svg class="diagram system-svg" viewBox="0 0 1100 260" aria-label="${esc(t.name)}系统能量链路"><defs><marker id="pa" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#0e607e"/></marker><marker id="sa" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#d94732"/></marker></defs>`;t.stages.forEach((s,i)=>{out+=moduleBox(x,91,w,s,i===0?t.direction:i===n-1?"负载/下一级":"功率转换级",i===n-1);if(i<n-1)out+=`<path class="power-wire" marker-end="url(#pa)" d="M${x+w} 129H${x+w+gap-5}"/>`;x+=w+gap});out+=`<path class="surge" marker-end="url(#sa)" d="M28 45V75H${gap+w/2}V88"/><text class="red-label" x="34" y="36">外部浪涌入口</text><text class="label" x="30" y="228">蓝色：正常能量流　红色虚线：外部瞬态进入路径；模块可继续下钻到器件级原理图。</text></svg>`;return out}
function commonDefs(){return `<defs><marker id="redarrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#d94732"/></marker></defs>`}
function label(x,y,a,b=""){return `<text class="ref" x="${x}" y="${y}">${a}</text>${b?`<text class="value" x="${x}" y="${y+17}">${b}</text>`:""}`}
function ground(x,y){return `<path class="symbol" d="M${x} ${y}V${y+18}M${x-18} ${y+18}H${x+18}M${x-12} ${y+25}H${x+12}M${x-6} ${y+32}H${x+6}"/>`}
function cap(x,y,ref,val){return `<g><path class="wire" d="M${x} ${y-38}V${y-9}M${x-18} ${y-9}H${x+18}M${x-18} ${y+9}H${x+18}M${x} ${y+9}V${y+38}"/>${label(x+25,y-8,ref,val)}</g>`}
function inductor(x,y,ref,val){return `<g><path class="wire" d="M${x-55} ${y}h12c0-24 24-24 24 0c0-24 24-24 24 0c0-24 24-24 24 0h14"/>${label(x-28,y-30,ref,val)}</g>`}
function fuse(x,y,ref){return `<g><path class="wire" d="M${x-45} ${y}H${x-27}M${x+27} ${y}H${x+45}"/><rect class="symbol" x="${x-27}" y="${y-12}" width="54" height="24"/>${label(x-17,y-22,ref,"FUSE")}</g>`}
function mosfet(x,y,ref,kind="SiC MOSFET"){return `<g><path class="symbol" d="M${x} ${y-34}V${y-12}M${x} ${y+12}V${y+34}M${x-2} ${y-12}V${y+12}M${x-18} ${y-13}V${y+13}M${x-40} ${y}H${x-18}M${x+9} ${y-17}l12 9M${x+9} ${y+17}l12-9"/>${label(x-36,y-43,ref,kind)}</g>`}
function diode(x,y,ref){return `<g><path class="wire" d="M${x-35} ${y}H${x-12}M${x+12} ${y}H${x+35}"/><path class="symbol" d="M${x-12} ${y-14}L${x+12} ${y}L${x-12} ${y+14}ZM${x+12} ${y-16}V${y+16}"/>${label(x-10,y-24,ref,"DIODE")}</g>`}
function transformer(x,y,ref){return `<g><path class="symbol" d="M${x-14} ${y-55}c-22 0-22 22 0 22c-22 0-22 22 0 22c-22 0-22 22 0 22c-22 0-22 22 0 22c-22 0-22 22 0 22M${x+14} ${y-55}c22 0 22 22 0 22c22 0 22 22 0 22c22 0 22 22 0 22c22 0 22 22 0 22c22 0 22 22 0 22M${x} ${y-62}V${y+62}"/>${label(x-28,y-76,ref,"HF XFMR")}</g>`}
function tvs(x,y,ref,val){return `<g><path class="tvs" d="M${x} ${y-38}V${y-13}M${x-18} ${y-13}H${x+18}M${x-14} ${y+9}H${x+14}M${x-15} ${y+9}l30-22M${x} ${y+9}V${y+38}"/>${label(x+24,y-7,ref,val)}</g>`}
function schematicPfc(t,totem=false,vienna=false){let s=`<svg class="diagram schematic-svg" viewBox="0 0 1100 440" aria-label="${esc(t.name)}器件级拓扑">${commonDefs()}<path class="wire" d="M55 150H980M55 310H980"/>${fuse(150,150,"F1")} ${inductor(300,150,"Lcm","EMI/CMC")}${cap(300,230,"Cx","X2")}${ground(300,310)}${tvs(215,230,"MOV1","AC SPD")}`;
if(vienna)s+=`${inductor(475,150,"La/Lb/Lc","BOOST")}${mosfet(610,230,"S1–S3","SiC")}${cap(780,205,"Cdc+","BUS")}${cap(780,275,"Cdc−","BUS")}${moduleBox(890,116,150,"700–800V DC-Link","分裂母线",true)}`;
else if(totem)s+=`${inductor(470,150,"L1","PFC")}${mosfet(600,205,"Q1/Q2","GaN/SiC")}${mosfet(705,205,"Q3/Q4","LF LEG")}${cap(835,230,"Cdc","400V")}${moduleBox(915,116,140,"DC-Link","400Vdc",true)}`;
else s+=`${diode(445,150,"BR1")}${inductor(580,150,"L1","PFC")}${diode(710,150,"Dboost")}${mosfet(645,245,"Q1","650V")}${cap(835,230,"Cdc","450V")}${moduleBox(915,116,140,"DC-Link","400Vdc",true)}`;
s+=`<path class="surge" marker-end="url(#redarrow)" d="M35 80V150H205V190"/><text class="red-label" x="36" y="68">IEC 61000-4-5 浪涌路径</text><path class="surge" marker-end="url(#redarrow)" d="M205 268V310"/><text class="label" x="45" y="390">一级保护：保险丝 + MOV/GDT/SPD　｜　二级保护：开关节点 Snubber/有源钳位　｜　TVS：控制、驱动与采样低压回路</text></svg>`;return s}
function schematicIsolated(t,dual=false){return `<svg class="diagram schematic-svg" viewBox="0 0 1100 440" aria-label="${esc(t.name)}器件级拓扑">${commonDefs()}<path class="wire" d="M55 115H400M55 325H400M700 115H1040M700 325H1040"/>${cap(110,220,"CIN",t.voltage.split("→")[0])}${mosfet(260,155,"Q1","PRIMARY")}${mosfet(260,285,"Q2","PRIMARY")}${inductor(410,175,"Lr","RESONANT")}${cap(490,175,"Cr","RESONANT")}${transformer(585,220,"T1")}${dual?`${mosfet(760,155,"Q5/Q6","SECONDARY")}${mosfet(760,285,"Q7/Q8","SECONDARY")}`:`${diode(760,155,"SR1")}${diode(760,285,"SR2")}`}${inductor(865,115,"Lo","OUTPUT")}${cap(945,220,"Co","OUTPUT")}<path class="tvs" d="M225 95H295M225 315H295"/>${tvs(345,220,"DTVS1","VDS CLAMP")}${moduleBox(900,70,145,"隔离输出","负载/母线",true)}<path class="surge" marker-end="url(#redarrow)" d="M55 65H345V174"/><text class="red-label" x="58" y="54">DC-Link 瞬态 / 漏感尖峰</text><text class="label" x="50" y="392">保护重点：原边 VDS 过冲、谐振腔异常、变压器漏感、同步整流反向恢复及输出短路能量</text></svg>`}
function schematicHvdc(t){return `<svg class="diagram schematic-svg" viewBox="0 0 1100 440" aria-label="${esc(t.name)}器件级拓扑">${commonDefs()}<path class="power-wire" d="M50 150H1050M50 305H1050"/>${fuse(130,150,"FHV1")}${tvs(220,228,"MOV-HV","HV SPD")}${moduleBox(300,116,150,"预充电单元","Rpre + Kpre")}${moduleBox(500,116,170,"固态断路器","背靠背 SiC",true)}${cap(740,228,"Cbus","±400/800V")}${moduleBox(835,116,180,"隔离 DC/DC","DAB/CLLC",true)}<path class="surge" marker-end="url(#redarrow)" d="M45 75V150H215V182"/><text class="red-label" x="50" y="62">HVDC 外部故障/浪涌</text><path class="control" d="M585 192V365H920"/><text class="label" x="595" y="354">绝缘监测 · 电弧检测 · 快速关断 · 放电控制</text><text class="label" x="50" y="403">注意：高压母线以高压 MOV、固态断路器和有源钳位为主；低压 TVS 仅用于辅助电源、驱动、采样与通信。</text></svg>`}
function schematicInverter(t,ups=false){return `<svg class="diagram schematic-svg" viewBox="0 0 1100 440" aria-label="${esc(t.name)}器件级拓扑">${commonDefs()}<path class="wire" d="M50 120H420M50 320H420M680 120H1035M680 320H1035"/>${moduleBox(60,86,150,ups?"PFC 整流":"整流/PFC","AC→DC")}${cap(290,220,"Cdc","DC-LINK")}${ups?moduleBox(390,238,180,"双向电池 DC/DC","充放电",true):moduleBox(390,238,180,"制动单元","Qbr + Rbr",true)}${mosfet(560,150,"Q1/Q2","LEG A")}${mosfet(650,290,"Q3/Q4","LEG B")}${inductor(790,120,"Lf","OUTPUT")}${cap(875,220,"Cf","FILTER")}${moduleBox(920,86,140,ups?"关键负载":"三相电机","AC LOAD",true)}${tvs(470,220,"DTVS","GATE/DRV")}<path class="surge" marker-end="url(#redarrow)" d="M55 60H470V174"/><text class="red-label" x="58" y="48">DC-Link 过压 / 关断尖峰</text><text class="label" x="50" y="398">栅极保护：G-S TVS + Miller Clamp + DESAT　｜　功率回路：RC/RCD Snubber、制动单元或有源钳位</text></svg>`}
function schematicBuck(t){return `<svg class="diagram schematic-svg" viewBox="0 0 1100 440" aria-label="${esc(t.name)}器件级拓扑">${commonDefs()}<path class="wire" d="M55 105H1035M55 330H1035"/>${tvs(145,220,"DTVS1","INPUT CLAMP")}${cap(235,220,"Cin","LOW ESR")}${mosfet(420,145,"QH","HIGH SIDE")}${mosfet(420,285,"QL","LOW SIDE")}${inductor(620,105,"L1","POWER")}${cap(795,220,"Cout","OUTPUT")}${moduleBox(885,71,150,"受保护负载",t.voltage,true)}<path class="wire" d="M420 179V251M420 215H565V105"/><path class="control" d="M340 215H380M340 285H380"/>${tvs(500,270,"DGS","G-S 15V")}<path class="surge" marker-end="url(#redarrow)" d="M55 48H145V174"/><text class="red-label" x="58" y="38">输入热插拔/线路浪涌</text><text class="label" x="55" y="395">输入钳位：TVS + Fuse/eFuse　｜　SW 节点：RC Snubber　｜　门极：串联电阻 + G-S TVS/Miller Clamp</text></svg>`}
function schematicFlyback(t){return `<svg class="diagram schematic-svg" viewBox="0 0 1100 440" aria-label="${esc(t.name)}器件级拓扑">${commonDefs()}<path class="wire" d="M55 105H430M55 330H430M700 105H1035M700 330H1035"/>${cap(125,220,"Cin","DC BUS")}${mosfet(330,260,"Q1","PRIMARY")}${transformer(565,210,"T1")}${diode(760,105,"Dsec/SR")}${cap(875,220,"Cout","OUTPUT")}${moduleBox(920,71,130,"负载","隔离输出",true)}<path class="wire" d="M430 105H540M430 330H330V294M590 105H725M590 330H1035"/>${tvs(390,185,"DCLAMP","RCD/TVS")}<path class="wire" d="M390 147V105M390 223V260"/><path class="surge" marker-end="url(#redarrow)" d="M300 85H390V140"/><text class="red-label" x="240" y="72">漏感关断尖峰</text><text class="label" x="55" y="395">原边漏感：RCD/有源钳位优先　｜　TVS：限制极端峰值但需校核平均损耗　｜　次级：RC Snubber/低压 TVS</text></svg>`}
function schematicSvg(t){return window.renderProfessionalSchematic(t)}
function renderList(){const q=document.querySelector("#search").value.toLowerCase(),fam=document.querySelector("#family-filter").value,ind=document.querySelector("#industry-filter").value;const list=topologies.filter(t=>(fam==="全部"||t.family===fam)&&(ind==="全部"||t.industries.includes(ind))&&Object.values(t).flat().join(" ").toLowerCase().includes(q));document.querySelector("#topology-list").innerHTML=list.map(t=>`<button class="topology-item ${t.id===activeId?'active':''}" data-id="${t.id}"><small>${t.family}</small><b>${t.name}</b><span>${t.direction} · ${t.voltage}</span></button>`).join("")||`<div class="empty">没有匹配的拓扑</div>`;document.querySelectorAll(".topology-item").forEach(b=>b.onclick=()=>{activeId=b.dataset.id;renderList();renderViewer()})}
function renderViewer(){const t=topologies.find(x=>x.id===activeId)||topologies[0];if(!t)return;document.querySelector("#viewer").innerHTML=`<div class="viewer-head"><div><small>${t.family} · ${t.direction}</small><h2>${t.name}</h2><p>${t.voltage} · ${t.power}</p></div><div class="badges">${t.industries.map(x=>`<span>${x}</span>`).join("")}</div></div><section class="diagram-card"><div class="cardbar"><h3>系统级能量链路</h3><div class="tools"><button data-zoom="system" data-delta="-.1">−</button><button data-reset="system">1:1</button><button data-zoom="system" data-delta=".1">＋</button></div></div><div class="canvas" data-canvas="system">${systemSvg(t)}</div></section><section class="diagram-card"><div class="cardbar"><h3>器件级功率拓扑与保护位置</h3><div class="tools"><button data-zoom="schematic" data-delta="-.1">−</button><button data-reset="schematic">1:1</button><button data-zoom="schematic" data-delta=".1">＋</button></div></div><div class="canvas" data-canvas="schematic">${schematicSvg(t)}</div></section><div class="detail-grid"><article class="info-card"><h3>行业应用与工作条件</h3><div class="kv"><b>典型设备</b><span>${t.applications.join("、")}</span><b>转换方向</b><span>${t.direction}</span><b>输入/输出</b><span>${t.voltage}</span><b>典型功率</b><span>${t.power}</span></div><div class="source">拓扑来源：${t.source}</div></article><article class="info-card"><h3>保护设计重点</h3><ol class="protection-list">${t.protection.map(x=>`<li>${x}</li>`).join("")}</ol></article></div>`;bindTools()}
function bindTools(){document.querySelectorAll("[data-zoom]").forEach(b=>b.onclick=()=>{const k=b.dataset.zoom;zoom[k]=Math.max(.6,Math.min(1.8,zoom[k]+Number(b.dataset.delta)));applyZoom(k)});document.querySelectorAll("[data-reset]").forEach(b=>b.onclick=()=>{zoom[b.dataset.reset]=1;applyZoom(b.dataset.reset)})}
function applyZoom(k){const svg=document.querySelector(`[data-canvas="${k}"] svg`);if(svg)svg.style.width=`${zoom[k]*100}%`}
function setupFilters(){const fams=[...new Set(topologies.map(x=>x.family))],inds=[...new Set(topologies.flatMap(x=>x.industries))];document.querySelector("#family-filter").innerHTML+=fams.map(x=>`<option>${x}</option>`).join("");document.querySelector("#industry-filter").innerHTML+=inds.map(x=>`<option>${x}</option>`).join("");["search","family-filter","industry-filter"].forEach(id=>document.querySelector(`#${id}`).addEventListener(id==="search"?"input":"change",renderList))}
function renderIndustries(){document.querySelector("#industry-map").innerHTML=Object.entries(flows).map(([name,steps])=>`<article class="industry-card"><h3>${name}</h3><div class="flow">${steps.map((x,i)=>`${i?'<i>→</i>':''}<span>${x}</span>`).join("")}</div><p>关联 ${topologies.filter(t=>t.industries.includes(name)).length} 个核心转换拓扑</p></article>`).join("")}
function renderInterfaces(){document.querySelector("#interface-grid").innerHTML=oldCircuits.map(c=>`<article class="interface-card"><small>${c.group||'端口保护'}</small><h3>${c.title}</h3><p>与行业系统和电源拓扑交叉引用，包含瞬态入口、钳位器件、后级耐压及测试标准。</p></article>`).join("")}
function wavePlot(kind){const paths={surge:`M48 145C78 144 98 136 120 46C132 22 145 68 162 98C190 132 230 143 345 145`,current:`M48 145C83 145 105 125 126 62C145 25 176 80 202 112C235 139 278 145 345 145`,esd:`M48 145L82 145L88 35L96 106L107 70L119 124L132 112L145 140H345`,switch:`M48 145H105L112 42L120 83L132 57L144 104L155 92L168 145H345`};const labels={surge:"1.2/50µs 开路电压",current:"8/20µs 短路电流",esd:"IEC ESD 电流示意",switch:"开关节点寄生振铃"};return `<svg viewBox="0 0 390 190" role="img" aria-label="${labels[kind]}"><path class="axis" d="M38 150H365M45 25V165"/><path class="trace" d="${paths[kind]}"/><path class="limit" d="M45 82H260"/><text x="55" y="32">${labels[kind]}</text><text x="267" y="76">保护阈值/钳位平台</text><text x="332" y="174">时间</text></svg>`}
function renderWaveforms(){document.querySelector("#waveform-grid").innerHTML=[["surge","组合波电压"],["current","8/20µs 电流"],["esd","系统级 ESD"],["switch","开关节点尖峰"]].map(([k,n])=>`<article class="wave-card"><h3>${n}</h3>${wavePlot(k)}</article>`).join("")}
document.querySelector("#topology-count").textContent=topologies.length;setupFilters();renderList();renderViewer();renderIndustries();renderInterfaces();renderWaveforms();
